```cypher
MATCH (s:Set {set_num: '31058-1'})-[:HAS_INVENTORY]->(inv:Inventory {version: 1})
MATCH (inv)-[e:CONTAINS_SET|CONTAINS_MINIFIG|HAS_PART*0..6]->(p:Part)
WHERE NOT EXISTS {
  MATCH (inv)-[e2:CONTAINS_SET|CONTAINS_MINIFIG|HAS_PART*0..6]->(p2:Part)
  WHERE p2 = p AND EXISTS {
    MATCH (inv)-[e3:CONTAINS_SET|CONTAINS_MINIFIG|HAS_PART*0..6]->(p3:Part)
    WHERE p3 = p AND e3.is_spare = true
  }
}
RETURN count(DISTINCT p.part_num)
```

