```cypher
MATCH (s:Set)-[:IN_THEME]->(t:Theme)
WHERE s.year = 2017
  AND (t.name = 'LEGO Brand Store'
       OR EXISTS {
         MATCH (t)-[:SUBTHEME_OF*1..10]->(parent:Theme)
         WHERE parent.name = 'LEGO Brand Store'
       })
RETURN COUNT(DISTINCT s) AS num_sets;
```

