```cypher
MATCH (t:Theme)
WHERE NOT EXISTS { MATCH (t)-[:SUBTHEME_OF]->(:Theme) }
MATCH (s:Set)-[:IN_THEME]->(sub:Theme)
WHERE s.year = 2013
  AND EXISTS { MATCH (sub)-[:SUBTHEME_OF*0..]->(t) }
RETURN t.name AS theme_name, COUNT(DISTINCT s) AS set_count
ORDER BY set_count DESC, t.name ASC
LIMIT 3;
```

```cypher
MATCH (mf:Minifig {fig_num: 'fig-014663'})
MATCH (p:Part {part_num: '14418'})
MATCH (s:Set)-[:HAS_INVENTORY]->(inv:Inventory)
WHERE inv.version = (SELECT MAX(i2.version) FROM (s)-[:HAS_INVENTORY]->(i2:Inventory))
AND EXISTS {
  MATCH (inv)-[:CONTAINS_MINIFIG]->(mf)
}
AND EXISTS {
  MATCH (inv)-[:HAS_PART]->(p)
  WHERE NOT EXISTS { MATCH (inv)-[hp:HAS_PART]->(p) WHERE hp.is_spare = true }
}
RETURN COUNT(DISTINCT s) AS count;
```

